DELETE FROM votes WHERE rowid NOT IN (
  SELECT MIN(rowid) FROM votes GROUP BY question_id, lower(voter_name)
);
CREATE UNIQUE INDEX idx_votes_q_name ON votes(question_id, lower(voter_name));
